  growCrop: {
    c1: "Los tomates van bien en tu zona con algo de planificación. Siémbralos en interior seis a ocho semanas antes de la última helada, endurécelos y trasplántalos cuando las noches superen los 50°F.",
    c2: "Los pimientos necesitan calor para arrancar en zonas templadas. Siémbralos pronto en interior, espera a que el suelo se caliente para trasplantar y espera la mayor cosecha a finales de verano.",
    c3: "La lechuga es un cultivo de primavera y otoño en tu zona: se espiga con el calor del verano. Siembra poco y a menudo y dale sombra por la tarde para alargar la temporada.",
    c4: "La espinaca va bien en tu zona en la mitad fresca del año. Siembra a principios de primavera y otra vez a finales de verano para un corte otoñal; se espigará si la siembras en pleno verano.",
    c5: "El kale es de los cultivos más fáciles en zonas templadas y aguanta casi todo el invierno. Siémbralo a mediados de verano para cosechar en otoño e invierno: las hojas se endulzan tras las primeras heladas.",
    c6: "Las coles rinden mejor antes y después del verano en tu zona. Siémbralas en interior y trasplántalas para una cosecha de primavera, o siembra a mediados de verano para una mejor en otoño, y protégelas con malla de la mariposa de la col.",
    c7: "Las zanahorias crecen bien en tu zona con una siembra a principios de primavera y otra a mediados de verano para raíces de otoño. Dales suelo profundo y sin piedras y aclara las plántulas, o saldrán bifurcadas y raquíticas.",
    c8: "El ajo es un cultivo clásico de zonas templadas y necesita tu invierno. Planta los dientes en otoño para que reciban el frío que necesitan para formar la cabeza, y cosecha cuando las hojas bajas se pongan marrones en pleno verano.",
    c9: "Los guisantes adoran el inicio fresco de la temporada. Siembra en cuanto se pueda trabajar el suelo, dales algo por donde trepar y recoge a menudo: dejan de producir cuando llega el calor.",
    c10: "Las judías son un cultivo de verano fiable en tu zona, pero odian el suelo frío. Siembra tras la última helada, haz una segunda tanda unas semanas después y sigue recogiendo para que no se paren.",
    c11: "Esta planta está a gusto en un verano templado una vez pasado el frío. Plántala tras la última helada en suelo rico, riega en la base y no sobre las hojas, y prepárate para más de lo que planeabas.",
    c12: "Los boniatos no son patatas y necesitan una temporada cálida que tu zona apenas ofrece. Planta esquejes enraizados bien pasada la última helada con el suelo caliente y cosecha antes de la primera helada de otoño.",
    c13: "Las patatas se adaptan a la larga primavera fresca de tu zona. Planta las patatas de siembra un par de semanas antes de la última helada, apórcalas al brotar y cosecha las tardías cuando se seque el follaje.",
    c14: "Las fresas son perennes en tu zona y producen más el segundo año. Plántalas en primavera u otoño, acolcha bajo los frutos para mantenerlos limpios y cubre las coronas en las semanas más frías.",
    c15: "La albahaca es la delicada del huerto templado. Mantenla en interior hasta que las noches superen con seguridad los 50°F, dale el sitio más soleado y despúntala para retrasar la floración.",
    c16: "Tu zona le da el frío invernal que necesita para fructificar bien, algo que las zonas cálidas no pueden. Planta un árbol a raíz desnuda en reposo, pódalo para abrir el centro y aclara una carga fuerte para que las ramas la aguanten.",
    c17: "Los tomates prosperan en zonas cálidas, pero necesitan riego profundo constante y acolchado para soportar el verano. Elige variedades tolerantes al calor como Solar Fire o Heatmaster.",
    c18: "Los pimientos están entre las mejores hortalizas para zonas cálidas: adoran el calor y producen en abundancia. Riega con constancia y disfruta de una temporada larga y productiva.",
    c19: "La albahaca prospera con calor y sol, perfecta para tu zona. Plántala tras la última helada a pleno sol y quítale las flores a menudo para que las hojas sigan sabrosas.",
    c20: "La sandía es una excelente opción para zonas cálidas: el calor acelera el crecimiento y el dulzor. Dale mucho espacio, riega a fondo cada semana y disfruta de una buena cosecha.",
    c21: "La okra es de las mejores hortalizas para climas cálidos y casi prospera sola. Plántala a pleno sol y cosecha cada 2 días en plena temporada.",
    c22: "La berenjena adora el calor y rinde de maravilla en zonas cálidas. Mantén el suelo siempre húmedo y disfruta de una temporada larga y productiva.",
    c23: "Los boniatos están hechos para zonas cálidas: adoran el calor y producen mucho en temporadas largas. Planta los esquejes tras la última helada y deja sitio a las guías.",
    c24: "El kale es de las mejores hortalizas para zonas frías: mejora su sabor tras las heladas. Plántalo a finales de verano para una cosecha de otoño e inicio del invierno cada vez más dulce.",
    c25: "La espinaca prospera en zonas frías y es de lo primero que se planta en primavera. Tolera heladas ligeras y da hojas tiernas con tiempo fresco.",
    c26: "Los guisantes son perfectos para zonas frías: prefieren el tiempo fresco y se siembran en cuanto el suelo se puede trabajar en primavera. Espera una buena cosecha antes del calor.",
    c27: "Las patatas se adaptan bien a zonas frías con temporadas largas y frescas. Planta patatas de siembra certificadas a principios de primavera y espera una buena cosecha a finales de verano.",
    c28: "Las zanahorias prosperan en climas frescos y se endulzan tras heladas ligeras. Siémbralas en suelo profundo, suelto y sin piedras para raíces rectas y grandes.",
    c29: "El brócoli es ideal para zonas frías: prefiere temperaturas frescas y rinde mejor en primavera u otoño. Siémbralo pronto en interior y trasplántalo cuando refresque para una cosecha excelente.",
  },
